{% extends 'base.html' %}

{% block title %}{{ username }} - {{ month_name_fr }} {{ year }}{% endblock %}

{% block content %}
<div class="d-flex justify-content-between mb-3">
    {% if user.is_staff %}
    <a class="btn btn-outline-primary" href="{% url 'admin_summary' %}?year={{ year }}&month={{ month }}">Page Admin</a>
    {% else %}
    <span></span>
    {% endif %}
    <div>
        <a class="btn btn-primary" href="{% url 'calendar' %}?year={{ prev_year }}&month={{ prev_month }}">&larr; Précédent</a>
        <a class="btn btn-primary" href="{% url 'calendar' %}?year={{ next_year }}&month={{ next_month }}">Suivant &rarr;</a>
        <a class="btn btn-outline-primary" href="{% url 'dashboard' %}">Tableau de bord</a>
        <a class="btn btn-outline-secondary" href="{% url 'logout' %}">Déconnexion</a>
    </div>
</div>

<h2 class="text-center mb-4">{{ username }} - {{ month_name_fr }} {{ year }}</h2>

<div class="row g-2 mb-4">
{% for d in days %}
    <div class="col-12 col-sm-6 col-md-4 col-lg-3 col-xl-1 calendar-day" id="day-{{ d.day }}" data-menu="{{ d.menu|escape }}" data-full-label="{{ d.full_label|escape }}" data-lunch="{{ d.lunch|default:''|escape }}" data-default-option="{{ d.default_option|escape }}" data-available-options="{{ d.available_options_json|escape }}" data-unavailable-notice="{{ d.unavailable_notice|default:''|escape }}" data-rating="{{ d.rating|default_if_none:'' }}" data-can-reserve="{{ d.can_reserve|yesno:'true,false' }}" data-can-select-lunch="{{ d.can_select_lunch|yesno:'true,false' }}" data-can-rate="{{ d.can_rate|yesno:'true,false' }}" {% if d.can_select_lunch or d.can_rate %}onclick="selectDay({{ d.day }})"{% endif %}>
        <div class="p-2 border rounded text-center h-100 selectable-day {% if not d.can_select_lunch and not d.can_rate %}locked-day{% endif %}">
            <div>{{ d.full_label }}</div>
            {% if d.lunch %}
            <div class="small text-muted lunch-label">{{ d.lunch }}</div>
            {% endif %}
        </div>
    </div>
    {% endfor %}
</div>

<div class="row justify-content-center">
    <div class="col-12 col-md-8 col-lg-6 col-xl-4">
        <div class="card shadow-sm calendar-selection-card">
            <div class="card-body text-center">
                <h4>Sélection du jour</h4>
                <p id="selectedDay">Aucun jour sélectionné</p>
                <p id="selectedLunch" class="text-muted small"></p>

                <div id="reservationSection">
                    <select id="lunchOption" class="form-select mb-3">
                        <option value="">-- Choisir un repas --</option>
                    </select>

                    <button id="saveLunchButton" class="btn btn-success w-100 mb-2" onclick="saveLunch()">Enregistrer le repas</button>
                    <button id="cancelLunchButton" class="btn btn-outline-danger w-100 mb-2" onclick="cancelLunch()">Annuler la réservation</button>
                </div>

                <div id="lunchUnavailableNotice" class="alert alert-warning small mt-3 mb-0 d-none"></div>

                <div id="ratingSection" class="mt-4 d-none">
                    <h5>Noter ce repas</h5>
                    <div id="ratingStars" class="rating-stars mb-2"></div>
                    <p id="ratingStatus" class="small text-muted mb-2"></p>
                </div>

                <div id="ratingUnavailableNotice" class="alert alert-warning small mt-3 mb-0 d-none">
                    La notation n'est pas encore disponible sur ce déploiement.
                </div>

                <p id="statusMsg" class="text-center small"></p>
            </div>
        </div>
    </div>
</div>

<script>
let selectedDay = null;
const year = {{ year }};
const month = {{ month }};
const ratingsEnabled = {{ ratings_enabled|yesno:'true,false' }};

function getCookie(name) {
    let cookieValue = null;
    if (document.cookie && document.cookie !== "") {
        const cookies = document.cookie.split(";");
        for (let i = 0; i < cookies.length; i++) {
            const cookie = cookies[i].trim();
            if (cookie.substring(0, name.length + 1) === (name + "=")) {
                cookieValue = decodeURIComponent(cookie.substring(name.length + 1));
                break;
            }
        }
    }
    return cookieValue;
}

function canRateDay(dayContainer) {
    return dayContainer.dataset.canRate === "true";
}

function getAvailableOptions(dayContainer) {
    return JSON.parse(dayContainer.dataset.availableOptions || "[]");
}

function selectDay(day, preserveStatusMessage = false) {
    document.querySelectorAll('.selectable-day').forEach(el => el.classList.remove('bg-primary', 'text-white'));
    const dayContainer = document.getElementById(`day-${day}`);
    const el = dayContainer.querySelector('.selectable-day');
    el.classList.add('bg-primary', 'text-white');

    selectedDay = day;
    const existingLunch = dayContainer.dataset.lunch;
    const defaultOption = dayContainer.dataset.defaultOption;
    const availableOptions = getAvailableOptions(dayContainer);
    const canRate = canRateDay(dayContainer);
    const existingRating = dayContainer.dataset.rating ? parseInt(dayContainer.dataset.rating, 10) : 0;
    const unavailableNotice = dayContainer.dataset.unavailableNotice;

    document.getElementById('selectedDay').innerText = dayContainer.dataset.fullLabel;
    document.getElementById('selectedLunch').innerText = existingLunch ? `Repas enregistré : ${existingLunch}` : "Aucune réservation enregistrée.";
    if (!preserveStatusMessage) {
        document.getElementById('statusMsg').innerText = "";
    }

    toggleReservationSection(availableOptions.length > 0 || Boolean(existingLunch));
    toggleLunchSelectionControls(availableOptions.length > 0);
    toggleCancelButton(Boolean(existingLunch));
    toggleLunchUnavailableNotice(unavailableNotice);
    toggleRatingSection(ratingsEnabled && canRate, existingRating);
    toggleRatingUnavailableNotice(!ratingsEnabled && canRate);
    syncLunchOption(existingLunch, defaultOption, availableOptions);
}

function toggleReservationSection(show) {
    const reservationSection = document.getElementById('reservationSection');
    reservationSection.classList.toggle('d-none', !show);
}

function toggleLunchSelectionControls(show) {
    document.getElementById('lunchOption').classList.toggle('d-none', !show);
    document.getElementById('saveLunchButton').classList.toggle('d-none', !show);
}

function toggleCancelButton(show) {
    document.getElementById('cancelLunchButton').classList.toggle('d-none', !show);
}

function toggleLunchUnavailableNotice(notice) {
    const noticeElement = document.getElementById('lunchUnavailableNotice');
    const show = Boolean(notice);
    noticeElement.classList.toggle('d-none', !show);
    noticeElement.innerText = show ? notice : "";
}

function toggleRatingSection(show, currentRating) {
    const ratingSection = document.getElementById('ratingSection');
    ratingSection.classList.toggle('d-none', !show);
    if (!show) {
        document.getElementById('ratingStars').innerHTML = "";
        document.getElementById('ratingStatus').innerText = "";
        return;
    }
    renderRatingStars(currentRating);
}

function toggleRatingUnavailableNotice(show) {
    document.getElementById('ratingUnavailableNotice').classList.toggle('d-none', !show);
}

function syncLunchOption(existingLunch, defaultOption, availableOptions) {
    const select = document.getElementById('lunchOption');
    select.innerHTML = "<option value=\"\">-- Choisir un repas --</option>";

    availableOptions.forEach((opt) => {
        const o = document.createElement('option');
        o.value = opt.name;
        o.textContent = opt.name;
        select.appendChild(o);
    });

    const names = availableOptions.map(opt => opt.name);
    select.value = names.includes(existingLunch) ? existingLunch : (names.includes(defaultOption) ? defaultOption : "");
}

function renderRatingStars(currentRating) {
    const container = document.getElementById('ratingStars');
    container.innerHTML = "";

    for (let rating = 1; rating <= 5; rating++) {
        const button = document.createElement('button');
        button.type = "button";
        button.className = `rating-star ${rating <= currentRating ? "is-selected" : ""}`;
        button.setAttribute("aria-label", `${rating} étoile${rating > 1 ? "s" : ""}`);
        button.innerText = rating <= currentRating ? "★" : "☆";
        button.addEventListener("click", () => saveMealRating(rating));
        container.appendChild(button);
    }

    document.getElementById('ratingStatus').innerText = currentRating ? `Note actuelle : ${currentRating}/5` : "Aucune note enregistrée.";
}

async function saveLunch() {
    const lunch = document.getElementById('lunchOption').value;
    if (!selectedDay || !lunch) {
        alert("Veuillez sélectionner un jour et un repas.");
        return;
    }

    const response = await fetch("{% url 'save_lunch' %}", {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
            "X-CSRFToken": getCookie("csrftoken")
        },
        body: JSON.stringify({ day: selectedDay, lunch, year, month })
    });

    const data = await response.json();
    document.getElementById('statusMsg').innerText = data.message || data.status;

    if (!response.ok) {
        return;
    }

    const dayContainer = document.getElementById(`day-${selectedDay}`);
    const dayBox = dayContainer.querySelector('.selectable-day');
    let label = dayBox.querySelector('.lunch-label');
    if (!label) {
        label = document.createElement('div');
        label.className = 'small text-muted lunch-label';
        dayBox.appendChild(label);
    }
    label.innerText = lunch;
    dayContainer.dataset.lunch = lunch;
    selectDay(selectedDay, true);
}

async function saveMealRating(rating) {
    if (!selectedDay) {
        alert("Veuillez sélectionner un jour.");
        return;
    }

    if (!ratingsEnabled) {
        alert("La notation n'est pas encore disponible.");
        return;
    }

    const dayContainer = document.getElementById(`day-${selectedDay}`);
    if (!dayContainer || dayContainer.dataset.canRate !== "true") {
        alert("La notation est réservée aux repas passés.");
        return;
    }

    const response = await fetch("{% url 'save_meal_rating' %}", {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
            "X-CSRFToken": getCookie("csrftoken")
        },
        body: JSON.stringify({ day: selectedDay, month, year, rating })
    });

    const data = await response.json();
    document.getElementById('statusMsg').innerText = data.message || data.status;

    if (!response.ok) {
        return;
    }

    dayContainer.dataset.rating = String(rating);
    renderRatingStars(rating);
}

async function cancelLunch() {
    if (!selectedDay) {
        alert("Veuillez sélectionner un jour.");
        return;
    }

    const response = await fetch("{% url 'save_lunch' %}", {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
            "X-CSRFToken": getCookie("csrftoken")
        },
        body: JSON.stringify({ day: selectedDay, lunch: "", year, month })
    });

    const data = await response.json();
    document.getElementById('statusMsg').innerText = data.message || data.status;

    if (!response.ok) {
        return;
    }

    const dayBox = document.querySelector(`#day-${selectedDay} .selectable-day`);
    const label = dayBox.querySelector('.lunch-label');
    if (label) {
        label.remove();
    }
    dayBox.parentElement.dataset.lunch = "";
    selectDay(selectedDay, true);
}
</script>
{% endblock %}

